{"question": "Viêm quanh Implant được chẩn đoán phân biệt với bệnh lý nào?", "claim": "Viêm quanh Implant cần được chẩn đoán phân biệt chủ yếu với bệnh viêm lợi quanh Implant dựa trên các triệu chứng lâm sàng.", "internal_evidence": [{"evidence_id": "I1", "content": "Chương 1: Mở đầu - Giới thiệu môn học Cắn khớp được nghiên cứu trong môn học cắn khớp có tác động qua lại với sự tiếp xúc giữa mặt nhai các răng..."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Triệu chứng | Viêm quanh Implant | Viêm lợi quanh Implant"}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Chảy máu lợi khi thăm khám | + | +"}, {"quote_id": "P2.Q3", "evidence_id": "P2", "text": "Viêm quanh Implant chẩn đóan phân biệt với Viêm lợi quanh Implant, và dựa vào các triệu chứng dưới đây:"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}]}
