{"question": "Triệu chứng lâm sàng và dấu hiệu nhận biết của áp xe tuyến dưới lưỡi là gì?", "claim": "Áp xe tuyến dưới lưỡi có đặc điểm là dấu hiệu ngoài miệng ít, sàn miệng bên bệnh sưng cứng và tình trạng khít hàm ít.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận tổn thương áp xe tuyến dưới lưỡi biểu hiện qua triệu chứng ít dấu hiệu ngoài miệng, sưng cứng sàn miệng bên bệnh và ít gây khít hàm."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Có khối u ở vùng lưỡi, má, trên mặt, vùng dưới hàm, bên cổ với các đặc điểm sau:"}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "- Áp xe tuyến dưới lưỡi: dấu hiệu ngoài miệng ít, sàn miệng bên bệnh sưng cứng, khít hàm ít."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "III. CHẨN ĐOÁN", "2 Chẩn đoán phân biệt"]}]}
