{"question": "Ung thư tuyến nước bọt mang tai có thể sử dụng hóa trị liệu vào những thời điểm nào trong phác đồ điều trị?", "claim": "Hóa trị liệu trong điều trị ung thư tuyến nước bọt mang tai có thể được sử dụng trước phẫu thuật và phối hợp điều trị sau phẫu thuật.", "internal_evidence": [{"evidence_id": "I1", "content": "Phác đồ điều trị ung thư tuyến nước bọt mang tai bao gồm việc ứng dụng hóa trị liệu trước khi tiến hành phẫu thuật cũng như phối hợp điều trị ở giai đoạn sau phẫu thuật."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Hóa trị liệu: có thể sử dụng trước phẫu thuật và phối hợp điều trị sau phẫu thuật."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Phẫu thuật cắt rộng lấy bỏ toàn bộ tổn thương ung thư bao gồm cả tuyến mang tai tới mô lành."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}]}
