{"question": "Bệnh celiac biểu hiện thương tổn và cảm giác như thế nào ở vị trí khoang miệng?", "claim": "Bệnh celiac khiến lưỡi ít khi bị tổn thương ở miệng và thường không gây ra bất kỳ cảm giác đau rát nào cho người bệnh.", "internal_evidence": [{"evidence_id": "I1", "content": "Chương 2: Giải phẫu chức năng hệ thống nhai mô tả mặt trên và mặt dưới của đĩa khớp thái dương hàm cùng cấu trúc mô sợi keo chắc chắn."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Khớp được hình thành bởi lồi cầu xương hàm dưới và ổ khớp của xương thái dương."}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Trật khớp TMJ ra trước xảy ra khi lồi cầu di chuyển ra phía trước và tiến về phía trước khớp."}, {"quote_id": "P1.Q3", "evidence_id": "P1", "text": "Trật khớp TMJ làm giãn các dây chằng của các dây chằng, ống động mạch trong và ngoài cùng, cơ thái dương, gây ra co thắt đau (trismus). Trismus ngăn không cho lồi cầu trở lại xương hàm dưới, ngăn chặn sự đóng kín của miệng."}, {"quote_id": "P1.Q4", "evidence_id": "P1", "text": "Khi lồi cầu được phục hồi vào xương hàm, hàm sẽ bị đóng lại dưới tác động của lực cơ, khiến cả lưỡi của bệnh nhân và ngón tay của người phẫu thuật có nguy cơ bị cắn."}, {"quote_id": "P1.Q5", "evidence_id": "P1", "text": "Trật khớp TMJ tự phát thường nhiều hơn hai bên so với một bên."}, {"quote_id": "P2.Q6", "evidence_id": "P2", "text": "loét áp tơ"}, {"quote_id": "P2.Q7", "evidence_id": "P2", "text": "viêm lưỡi thể teo"}, {"quote_id": "P2.Q8", "evidence_id": "P2", "text": "Hội chứng rát miệng (glossodynia)"}, {"quote_id": "P2.Q9", "evidence_id": "P2", "text": "Bệnh do nấm candida ở miệng (tưa miệng)"}, {"quote_id": "P2.Q10", "evidence_id": "P2", "text": "Nhiễm trùng khoang dưới hàm (đau thắt ngực Ludwig): liên quan đến các khoang dưới lưỡi, dưới hàm và dưới cằm và có thể khiến cho lưỡi bị đẩy cao lên."}, {"quote_id": "P2.Q11", "evidence_id": "P2", "text": "Bệnh celiac (lưỡi là vị trí ở miệng bị thương tổn nhiều nhất; biểu hiện bằng cảm giác đau rát)"}], "public_sources": [{"evidence_id": "P1", "title": "Cách nắn chỉnh trật khớp hàm dưới", "heading_path": ["Giải phẫu liên quan trong nắn chỉnh trật khớp hàm dưới"]}, {"evidence_id": "P2", "title": "Lưỡi khó chịu", "heading_path": []}]}
