{"question": "U bạch mạch ở vùng hàm mặt thường xuất hiện tại những vị trí giải phẫu nào?", "claim": "U bạch mạch có thể xuất hiện dưới dạng khối u ở vùng lưỡi, má, trên mặt, vùng dưới hàm, bên cổ.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận u bạch mạch thường biểu hiện bằng các khối u tại vùng lưỡi, má, trên mặt, vùng dưới hàm và bên cổ."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Sưng nề và tụ máu: Tùy theo vị trí, mức độ chấn thương mà dấu hiệu sưng nề và tụ máu có những mức độ nhiều ít khác nhau, có thể gặp ở ngoài hoặc trong miệng."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "Có khối u ở vùng lưỡi, má, trên mặt, vùng dưới hàm, bên cổ với các đặc điểm sau:"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["54. GÃY XƯƠNG HÀM DƯỚI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Triệu chứng lâm sàng gãy xương hàm dưới"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH"]}]}
