{"question": "Triệu chứng toàn thân của bệnh nhân bị áp xe má ở giai đoạn chẩn đoán xác định gồm những gì?", "claim": "Bệnh nhân bị áp xe má có biểu hiện nhiễm trùng toàn thân bao gồm sốt cao, mạch nhanh và hơi thở hôi.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận tình trạng nhiễm trùng toàn thân ở bệnh nhân áp xe má với các dấu hiệu sốt cao, nhịp tim nhanh và hơi thở hôi."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Có biểu hiện nhiễm trùng: sốt cao, mạch nhanh, hơi thở hôi…."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Trường hợp u bị bội nhiễm: có cảm giác đau, niêm mạc và da trên u đỏ, các răng trên u lung lay nhiều. Bệnh nhân có sốt và xuất hiện hạch vùng ngoại vi."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["30. ÁP XE MÁ", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "a. Toàn thân"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["36. U MEN XƯƠNG HÀM", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Giai đoạn u to làm phồng xương hàm"]}]}
