{"question": "Quy trình điều trị cụ thể cho bệnh lý u xương răng là gì?", "claim": "Điều trị cụ thể cho u xương răng là thực hiện phẫu thuật tách bóc để bộc lộ hoàn toàn khối u.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu chuyên khoa hướng dẫn phẫu thuật bộc lộ và tách bóc khối u xương răng ra khỏi xương hàm."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Khám định kỳ để phát hiện tổn thương sớm và điều trị kịp thời, nhất là ở các trường hợp nguy cơ cao như bệnh nhân có tiền sử viêm quanh răng, bệnh nhân mắc bệnh tiểu đường, hút thuốc lá, điều trị corticoid kéo dài,…."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "- Tách bóc bộc lộ khối u."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "VI. PHÒNG BỆNH"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["38. U XƯƠNG RĂNG", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}]}
