{"question": "Kết quả phân loại độ nặng của hội chứng nhiễm trùng huyết do nhiễm trùng răng miệng với CRP và PCT ở mức nghiêm trọng (Severe) là bao nhiêu trường hợp?", "claim": "Theo kết quả nghiên cứu về các dấu ấn sinh học CRP và PCT đối với độ nặng của nhiễm trùng huyết do nguồn gốc răng miệng, có 17 trường hợp đạt tiêu chuẩn phân loại mức độ nặng (Severe) đối với cả kết quả xét nghiệm C-Reactive Protein và Procalcitonin.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu ghi nhận số lượng kết quả xét nghiệm CRP và PCT trong nhóm mức độ nặng (Severe) đều là 17 trường hợp theo bảng phân loại mới."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Table 4"}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "New severity classification for C-reactive protein (CRP) and procalcitonin (PCT)"}, {"quote_id": "P1.Q3", "evidence_id": "P1", "text": "Scoring criteria | Count of C-reactive protein results | Count of procalcitonin results"}, {"quote_id": "P1.Q4", "evidence_id": "P1", "text": "Severe | 17 | 17"}, {"quote_id": "P2.Q5", "evidence_id": "P2", "text": "Table 4"}, {"quote_id": "P2.Q6", "evidence_id": "P2", "text": "New severity classification for C-reactive protein (CRP) and procalcitonin (PCT)"}, {"quote_id": "P2.Q7", "evidence_id": "P2", "text": "Scoring criteria | Count of C-reactive protein results | Count of procalcitonin results"}, {"quote_id": "P2.Q8", "evidence_id": "P2", "text": "17.3 | 1 | 1"}], "public_sources": [{"evidence_id": "P1", "title": "Comparison of C-Reactive Protein and Procalcitonin as Biomarkers for Severity of Sepsis in Odontogenic Infection", "heading_path": ["Body", "Results"]}, {"evidence_id": "P2", "title": "Comparison of C-Reactive Protein and Procalcitonin as Biomarkers for Severity of Sepsis in Odontogenic Infection", "heading_path": ["Body", "Results"]}]}
