{"question": "Triệu chứng lâm sàng khi u tuyến nước bọt mang tai dính với mô xung quanh như thế nào?", "claim": "U tuyến nước bọt mang tai có đặc điểm lâm sàng là u dính với mô xung quanh.", "internal_evidence": [{"evidence_id": "I1", "content": "Chương 2: Giải phẫu chức năng hệ thống nhai duy trì tiếp xúc giữa phần trung tâm của đĩa với điện khớp ở lồi cầu."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ U dính với mô xung quanh."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "Có khối u ở vùng lưỡi, má, trên mặt, vùng dưới hàm, bên cổ với các đặc điểm sau:"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["51. UNG THƯ TUYẾN NƯỚC BỌT MANG TAI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["40. U BẠCH MẠCH"]}]}
