{"question": "Nguyên nhân nào dẫn đến tình trạng áp xe vùng dưới hàm?", "claim": "Áp xe vùng dưới hàm có thể bắt nguồn từ nguyên nhân do sỏi tuyến nước bọt nhiễm khuẩn.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận tình trạng nhiễm khuẩn xuất phát từ sỏi tuyến nước bọt là một trong các nguyên nhân gây ra áp xe vùng dưới hàm."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Đối với tình trạng viêm quanh Implant ở giai đoạn ban đầu có nguyên nhân do cấu trúc phục hình hoặc lực nhai quá tải thì tiên lượng điều trị rất khả quan, tuy nhiên đối với tình trạng viêm quanh Implant ở giai đoạn tiến triển trên bệnh nhân bị bệnh viêm quanh răng hoặc không xác định được nguyên nhân gây bệnh thì kết quả điều trị ít khả quan và bệnh vẫn có nguy cơ tiến triển dẫn đến việc phải tháo bỏ Implant."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Sỏi tuyến nước bọt nhiễm khuẩn."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["52. VIÊM QUANH IMPLANT", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "II. NGUYÊN NHÂN"]}]}
