{"question": "Phương pháp điều trị tại chỗ nào cần được thực hiện đối với áp xe vùng dưới hàm?", "claim": "Điều trị tại chỗ cho bệnh nhân áp xe vùng dưới hàm bao gồm việc thực hiện điều trị răng nguyên nhân.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng hướng dẫn quy trình điều trị tại chỗ đối với áp xe vùng dưới hàm là tiến hành điều trị dứt điểm răng nguyên nhân."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Nếu dẫn lưu mủ phối hợp với điều trị răng nguyên nhân thì có kết quả điều trị tốt."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Điều trị răng nguyên nhân."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["31. ÁP XE VÙNG DƯỚI HÀM", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Điều trị tại chỗ"]}]}
